<?php
namespace App\Notifications;
use Illuminate\Bus\Queueable; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class PasswordResetNotification extends Notification { use Queueable; public function __construct(protected string $token) {} public function via($notifiable):array{return ['mail'];} public function toMail($notifiable):MailMessage{$url=rtrim(config('app.frontend_url'),'/').'/reset-password?token='.urlencode($this->token).'&user_id='.$notifiable->id; return (new MailMessage)->subject('Reset your password')->greeting("Hello {$notifiable->name},")->line('You requested a password reset. Click below to choose a new password.')->action('Reset Password',$url)->line("This link expires in 60 minutes. If you didn't request this, you can ignore this email.");}}
